def along(p0, p1, step, start=0.0):
    dx = p1[0] - p0[0]; dy = p1[1] - p0[1]
    L = math.hypot(dx, dy)
    t = start
    out = []
    while t <= L + 1e-6:
        out.append((p0[0] + dx * t / L, p0[1] + dy * t / L))
        t += step
    return out

def perp(p0, p1):
    dx = p1[0] - p0[0]; dy = p1[1] - p0[1]
    L = math.hypot(dx, dy)
    return (-dy / L, dx / L)

for svc, step, lateral, zlo, zhi in (
