def separation_gate():
    worst = None
    for t in SOLIDS:
        if t["grp"] != "Tray":
            continue
        for b in SOLIDS:
            if b["grp"] != "Busway":
                continue
            ax0, ay0, az0, ax1, ay1, az1 = t["box"]
            bx0, by0, bz0, bx1, by1, bz1 = b["box"]
            gx = max(bx0 - ax1, ax0 - bx1)
