import struct, zlib, numpy as np

def load(path):
    d=open(path,'rb').read(); i=8; idat=b''
    while i<len(d):
        ln=struct.unpack(">I",d[i:i+4])[0]; t=d[i+4:i+8]
        if t==b'IHDR': w,h,bd,ct,cm,fl,il=struct.unpack(">IIBBBBB",d[i+8:i+21])
        if t==b'IDAT': idat+=d[i+8:i+8+ln]
        i+=12+ln
    raw=zlib.decompress(idat); bpp=4; stride=w*bpp
    out=np.zeros((h,stride),np.uint8); prev=np.zeros(stride,np.uint8); p=0
    for y in range(h):
        f=raw[p]; p+=1
        line=np.frombuffer(raw[p:p+stride],np.uint8).copy(); p+=stride
        if f==0: cur=line
        elif f==1:
            cur=line
            for x in range(bpp,stride): cur[x]=(int(cur[x])+int(cur[x-bpp]))&0xff
        elif f==2: cur=(line.astype(np.int16)+prev).astype(np.uint8)
        elif f==3:
            cur=line.copy()
            for x in range(stride):
                a=cur[x-bpp] if x>=bpp else 0
                cur[x]=(int(line[x])+((int(a)+int(prev[x]))>>1))&0xff
        else:
            cur=line.copy()
            for x in range(stride):
                a=int(cur[x-bpp]) if x>=bpp else 0; b=int(prev[x]); c=int(prev[x-bpp]) if x>=bpp else 0
                pp=a+b-c; pa,pb,pc=abs(pp-a),abs(pp-b),abs(pp-c)
                pr=a if (pa<=pb and pa<=pc) else (b if pb<=pc else c)
                cur[x]=(int(line[x])+pr)&0xff
        out[y]=cur; prev=cur
    return out.reshape(h,w,4)

