def placement_local(p):
    """accumulate IfcLocalPlacement chain -> (origin, axis, ref) in file units"""
    chain=[]
    while p is not None:
        rp = p.RelativePlacement
        chain.append(rp)
        p = p.PlacementRelTo
    chain.reverse()
    M = np.eye(4)
    for rp in chain:
        loc = rp.Location.Coordinates
        ax = rp.Axis.DirectionRatios if rp.Axis else (0.,0.,1.)
        rd = rp.RefDirection.DirectionRatios if rp.RefDirection else (1.,0.,0.)
        ax = np.array(ax,float); ax/=np.linalg.norm(ax)
        rd = np.array(rd,float); rd = rd - ax*np.dot(rd,ax); rd/=np.linalg.norm(rd)
        ry = np.cross(ax,rd)
        T = np.eye(4)
        T[:3,0]=rd; T[:3,1]=ry; T[:3,2]=ax; T[:3,3]=np.array(loc,float)
        M = M @ T
    return M

def aabb(e):
    rep = e.Representation
    if rep is None: return None
    for sr in rep.Representations:
        for it in sr.Items:
            if it.is_a('IfcExtrudedAreaSolid'):
                prof = it.SweptArea
                depth = it.Depth
                M = placement_local(e.ObjectPlacement) @ placement_local_matrix(it.Position)
                # profile local points
                if prof.is_a('IfcRectangleProfileDef'):
                    w,h = prof.XDim, prof.YDim
                    loc = prof.Position.Location.Coordinates if prof.Position else (0.,0.)
                    pts = [(loc[0]+sx*w/2, loc[1]+sy*h/2, zz) for sx in(-1,1) for sy in(-1,1) for zz in (0.,depth)]
                elif prof.is_a('IfcCircleProfileDef'):
                    r = prof.Radius
                    pts = [(sx*r, sy*r, zz) for sx in(-1,1) for sy in(-1,1) for zz in (0.,depth)]
                elif prof.is_a('IfcArbitraryClosedProfileDef'):
                    p2 = [(p.Coordinates[0],p.Coordinates[1]) for p in prof.OuterCurve.Points]
                    pts = [(x,y,zz) for (x,y) in p2 for zz in (0.,depth)]
                else:
                    return None
                P = np.array([[M[0,0]*x+M[0,1]*y+M[0,2]*z+M[0,3],
                               M[1,0]*x+M[1,1]*y+M[1,2]*z+M[1,3],
                               M[2,0]*x+M[2,1]*y+M[2,2]*z+M[2,3]] for (x,y,z) in pts])
