import numpy as np
from collections import deque, Counter
from png import load, gray

def comps4(mask):
    H,W=mask.shape
    lab=np.zeros((H,W),np.int32); n=0; out=[]
    for y0,x0 in zip(*np.nonzero(mask)):
        if lab[y0,x0]: continue
        n+=1; q=deque([(y0,x0)]); lab[y0,x0]=n; pts=[]
        while q:
            cy,cx=q.popleft(); pts.append((cy,cx))
            for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                ny,nx=cy+dy,cx+dx
                if 0<=ny<H and 0<=nx<W and mask[ny,nx] and lab[ny,nx]==0:
                    lab[ny,nx]=n; q.append((ny,nx))
        out.append(pts)
    return out

def cells(g,x0,x1,y0,y1,thr=150,minink=3):
    sub=g[y0:y1,x0:x1]; m=sub<thr
    out=[]
    for pts in comps4(m):
        ys=[p[0] for p in pts]; xs=[p[1] for p in pts]
        if len(pts)<minink: continue
        h=max(ys)-min(ys)+1; w=max(xs)-min(xs)+1
        if h<4: continue
        out.append((min(xs)+x0,min(ys)+y0,w,h,pts,min(xs),min(ys)))
    return sorted(out)

