import numpy as np, png
def lum(p):
    a=png.load(p); return a[:,:,:3].astype(np.int32).mean(axis=2)

class OCR:
    def __init__(self,L,thr=235):
        self.L=L; self.thr=thr
    def glyphs(self,x0,x1,y0,y1):
        m=(self.L[y0:y1+1,x0:x1+1]<self.thr)
        cols=m.any(axis=0)
        seg=[];s=None
        for i,v in enumerate(cols):
            if v and s is None: s=i
            if not v and s is not None: seg.append((s,i-1)); s=None
        if s is not None: seg.append((s,len(cols)-1))
        out=[]
        for (a,b) in seg:
            band=m[:,a:b+1]
            rows=np.nonzero(band.any(axis=1))[0]
            out.append((x0+a,x0+b,y0+rows[0],y0+rows[-1],band[rows[0]:rows[-1]+1]))
        return out
    def lines(self,x0,x1,y0,y1,minh=3):
        m=(self.L[y0:y1,x0:x1]<self.thr)
        rows=m.sum(axis=1)
        seg=[];s=None
        for i,v in enumerate(rows>0):
            if v and s is None: s=i
            if not v and s is not None: seg.append((s,i-1)); s=None
        if s is not None: seg.append((s,len(rows)-1))
        return [(y0+a,y0+b) for (a,b) in seg if b-a+1>=minh]
