import numpy as np
def label(mask):
    h,w=mask.shape
    lab=np.zeros((h,w),np.int32); cur=0; out=[]
    for y in range(h):
        for x in range(w):
            if mask[y,x] and lab[y,x]==0:
                cur+=1; stack=[(y,x)]; lab[y,x]=cur; pts=[]
                while stack:
                    yy,xx=stack.pop(); pts.append((yy,xx))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=yy+dy,xx+dx
                        if 0<=ny<h and 0<=nx<w and mask[ny,nx] and lab[ny,nx]==0:
                            lab[ny,nx]=cur; stack.append((ny,nx))
                ys=[p[0] for p in pts]; xs=[p[1] for p in pts]
                out.append((min(xs),min(ys),max(xs),max(ys),len(pts)))
    return out
